1714	fn styled_line_spans(
1715	    line: &str,
1716	    selection_range: Option<(usize, usize)>,
1717	    base_style: Style,
1718	) -> Vec<Span<'static>> {
1719	    let Some((start, end)) = selection_range else {
1720	        return vec![Span::styled(line.to_string(), base_style)];
1721	    };
1722	
1723	    let line_len = line.chars().count();
1724	    let start = start.min(line_len);
1725	    let end = end.min(line_len);
1726	    if start >= end {
1727	        return vec![Span::styled(line.to_string(), base_style)];
1728	    }
1729	
1730	    let selected_style = base_style.add_modifier(Modifier::REVERSED);
1731	    let mut spans = Vec::new();
1732	    if start > 0 {
1733	        spans.push(Span::styled(slice_chars(line, 0, start), base_style));
1734	    }
1735	    spans.push(Span::styled(slice_chars(line, start, end), selected_style));
1736	    if end < line_len {
1737	        spans.push(Span::styled(slice_chars(line, end, line_len), base_style));
1738	    }
1739	    spans
1740	}
