1746	) -> Option<(usize, usize)> {
1747	    match selection.kind {
1748	        VisualKind::Line => {
1749	            let start_row = selection.anchor.row.min(selection.cursor.row);
1750	            let end_row = selection.anchor.row.max(selection.cursor.row);
1751	            (start_row..=end_row)
1752	                .contains(&row)
1753	                .then_some((0, line_len))
1754	        }
1755	        VisualKind::Character => visual_character_range(selection, row, line_len),
