1760	fn visual_character_range(
1761	    selection: &VisualSelection,
1762	    row: usize,
1763	    line_len: usize,
1764	) -> Option<(usize, usize)> {
1765	    let (start, end) = ordered_positions(selection.anchor, selection.cursor);
1766	    if row < start.row || row > end.row {
1767	        return None;
1768	    }
1769	    if line_len == 0 {
1770	        return Some((0, 0));
1771	    }
1772	
1773	    let last = line_len.saturating_sub(1);
1774	    let start_column = if row == start.row {
1775	        start.column.min(last)
1776	    } else {
1777	        0
1778	    };
1779	    let end_column = if row == end.row {
1780	        end.column.min(last)
1781	    } else {
1782	        last
1783	    };
1784	    Some((
1785	        start_column.min(line_len),
1786	        end_column.saturating_add(1).min(line_len),
1787	    ))
1788	}
